1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Item {
6	  type: string;
7	  material?: string;
8	  enchantment?: number;
9	  cursed?: boolean;
10	}
11	
12	export interface QuoteStep {
13	  op: "quote";
14	  items: Item[];
15	}
16	
17	export interface Damage {
18	  itemType: string;
19	  amount: number;
20	}
21	
22	export interface Incident {
23	  cause: string;
24	  damages: Damage[];
25	}
26	
27	export interface ClaimStep {
28	  op: "claim";
29	  policy: number;
30	  incident: Incident;
31	}
32	
33	export type Step = QuoteStep | ClaimStep;
34	
35	export interface Scenario {
36	  customer: Customer;
37	  steps: Step[];
38	}
39	
40	export interface QuoteResult {
41	  premium: number;
42	}
43	
44	export interface ClaimResult {
45	  payout: number;
46	  remainingCap: number;
47	}
48	
49	export type StepResult = QuoteResult | ClaimResult;
50	
51	export interface ScenarioOutput {
52	  results: StepResult[];
53	}
54	
55	const PROCESSING_FEE = 5;
56	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
57	const CURSE_SURCHARGE_RATE = 0.5;
58	const HIGH_ENCHANTMENT_THRESHOLD = 5;
59	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
60	const LOYALTY_THRESHOLD_YEARS = 2;
61	const LOYALTY_DISCOUNT_RATE = 0.2;
62	const FOLLOW_UP_CONTRACT_DISCOUNT_RATE = 0.15;
63	const DEDUCTIBLE_PER_DAMAGE = 100;
64	const CAP_MULTIPLIER = 2;
65	const HALF_REIMBURSEMENT_ENCHANTMENT = 8;
66	const HALF_REIMBURSEMENT_RATE = 0.5;
67	
68	const INSURANCE_VALUES: Record<string, number> = {
69	  sword: 1000,
70	  amulet: 600,
71	  staff: 800,
72	  potion: 400,
73	  rune: 250,
74	  moonstone: 250,
75	};
76	
77	const BASE_PREMIUMS: Record<string, number> = {
78	  sword: 100,
79	  amulet: 60,
80	  staff: 80,
81	  potion: 40,
82	  rune: 25,
83	  moonstone: 25,
84	};
85	
86	const BLOCK_SIZE = 3;
87	const BLOCK_BASE_PREMIUM = 60;
88	
89	const countByType = (items: Item[]): Map<string, number> => {
90	  const counts = new Map<string, number>();
91	  for (const item of items) {
92	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
93	  }
94	  return counts;
95	};
96	
97	const basePremiumOfType = (type: string): number => BASE_PREMIUMS[type];
98	
99	const basePremiumOfAlikeItems = (type: string, count: number): number =>
100	  count === BLOCK_SIZE ? BLOCK_BASE_PREMIUM : count * basePremiumOfType(type);
101	
102	const policyBasePremium = (items: Item[]): number =>
103	  [...countByType(items)].reduce(
104	    (total, [type, count]) => total + basePremiumOfAlikeItems(type, count),
105	    0,
106	  );
107	
108	const firstInsuranceSurcharge = (policyBase: number): number =>
109	  policyBase * FIRST_INSURANCE_SURCHARGE_RATE;
110	
111	const itemBasePremium = (item: Item): number => basePremiumOfType(item.type);
112	
113	const isCursed = (item: Item): boolean => item.cursed === true;
114	
115	const isHighlyEnchanted = (item: Item): boolean =>
116	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
117	
118	const curseSurcharge = (item: Item): number =>
119	  isCursed(item) ? itemBasePremium(item) * CURSE_SURCHARGE_RATE : 0;
120	
121	const highEnchantmentSurcharge = (item: Item): number =>
122	  isHighlyEnchanted(item)
123	    ? itemBasePremium(item) * HIGH_ENCHANTMENT_SURCHARGE_RATE
124	    : 0;
125	
126	const itemSurchargeTotal = (items: Item[]): number =>
127	  items.reduce(
128	    (total, item) => total + curseSurcharge(item) + highEnchantmentSurcharge(item),
129	    0,
130	  );
131	
132	const loyaltyDiscount = (policyBase: number, customer: Customer): number =>
133	  customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS
134	    ? policyBase * LOYALTY_DISCOUNT_RATE
135	    : 0;
136	
137	const followUpContractDiscount = (policyBase: number, previousQuotes: number): number =>
138	  previousQuotes > 0 ? policyBase * FOLLOW_UP_CONTRACT_DISCOUNT_RATE : 0;
139	
140	const policyWideAdjustments = (
141	  policyBase: number,
142	  customer: Customer,
143	  previousQuotes: number,
144	): number =>
145	  firstInsuranceSurcharge(policyBase) -
146	  loyaltyDiscount(policyBase, customer) -
147	  followUpContractDiscount(policyBase, previousQuotes);
148	
149	const quote = (
150	  step: QuoteStep,
151	  customer: Customer,
152	  previousQuotes: number,
153	): QuoteResult => {
154	  const policyBase = policyBasePremium(step.items);
155	  const premiumBeforeRounding =
156	    policyBase +
157	    itemSurchargeTotal(step.items) +
158	    policyWideAdjustments(policyBase, customer, previousQuotes) +
159	    PROCESSING_FEE;
160	  return { premium: Math.ceil(premiumBeforeRounding) };
161	};
162	
163	interface Policy {
164	  items: Item[];
165	  remainingCap: number;
166	}
167	
168	const insuranceSum = (items: Item[]): number =>
169	  items.reduce((total, item) => total + INSURANCE_VALUES[item.type], 0);
170	
171	const isHalfReimbursed = (item: Item): boolean =>
172	  (item.enchantment ?? 0) >= HALF_REIMBURSEMENT_ENCHANTMENT;
173	
174	const reimbursedAmount = (damage: Damage, item: Item): number =>
175	  isHalfReimbursed(item) ? damage.amount * HALF_REIMBURSEMENT_RATE : damage.amount;
176	
177	const payoutForDamage = (damage: Damage, item: Item): number =>
178	  Math.max(0, reimbursedAmount(damage, item) - DEDUCTIBLE_PER_DAMAGE);
179	
180	const claim = (step: ClaimStep, policy: Policy): ClaimResult => {
181	  const payout = step.incident.damages.reduce(
182	    (total, damage) =>
183	      total +
184	      payoutForDamage(
185	        damage,
186	        policy.items.find((item) => item.type === damage.itemType)!,
187	      ),
188	    0,
189	  );
190	  policy.remainingCap -= payout;
191	  return { payout: Math.floor(payout), remainingCap: policy.remainingCap };
192	};
193	
194	const policyFor = (items: Item[]): Policy => ({
195	  items,
196	  remainingCap: insuranceSum(items) * CAP_MULTIPLIER,
197	});
198	
199	const countQuotesBefore = (steps: Step[], stepIndex: number): number =>
200	  steps.slice(0, stepIndex).filter((step) => step.op === "quote").length;
201	
202	export const runScenario = (scenario: Scenario): ScenarioOutput => {
203	  // A policy is registered under the index of the step that quoted it; that
204	  // step index is the id later claim steps refer to. Claims mutate their
205	  // policy's remainingCap, so the register carries state across steps.
206	  const policies = new Map<number, Policy>();
207	
208	  const results = scenario.steps.map((step, stepIndex): StepResult => {
209	    if (step.op === "claim") {
210	      return claim(step, policies.get(step.policy)!);
211	    }
212	    policies.set(stepIndex, policyFor(step.items));
213	    return quote(
214	      step,
215	      scenario.customer,
216	      countQuotesBefore(scenario.steps, stepIndex),
217	    );
218	  });
219	
220	  return { results };
221	};
